<?php
declare(strict_types=1);
use Sentinel\Core\{Container,Router,Request,Response};
return static function(Router $router,Container $container):void {
    $opts=static fn(string $p):array=>['auth'=>true,'tenant'=>true,'permission'=>$p];
    $json=static fn(mixed $data):Response=>Response::json(['data'=>$data])->withHeader('Cache-Control','no-store');
    $keys=static fn()=>$container->make('key_custody_service');$suggest=static fn()=>$container->make('replacement_suggestion_service');$emergency=static fn()=>$container->make('emergency_procedure_service');$company=static fn()=>$container->make('company_workspace_service');$language=static fn()=>$container->make('workflow_language_service');
    $router->get('/api/v1/key-register',static fn(Request $r):Response=>$json($keys()->assets($r->queryParams())),$opts('key_register.view'));
    $router->post('/api/v1/key-register',static fn(Request $r):Response=>$json($keys()->create($r->json())),$opts('key_register.manage'));
    $router->get('/api/v1/key-register/{id}/history',static fn(Request $r,array $p):Response=>$json($keys()->history((string)$p['id'])),$opts('key_register.view'));
    $router->post('/api/v1/key-register/{id}/issue',static fn(Request $r,array $p):Response=>$json($keys()->issue((string)$p['id'],$r->json())),$opts('key_register.manage'));
    $router->post('/api/v1/key-register/{id}/state',static fn(Request $r,array $p):Response=>$json($keys()->assetAction((string)$p['id'],$r->json())),$opts('key_register.manage'));
    foreach(['receive','cancel','lost']as$action)$router->post('/api/v1/key-loans/{id}/'.$action,static fn(Request $r,array $p):Response=>$json($keys()->manageLoan((string)$p['id'],$action,$r->json())),$opts('key_register.manage'));
    $router->get('/api/v1/my-keys',static fn():Response=>$json($keys()->mine()),$opts('key_register.self'));
    $router->get('/api/v1/key-loans/{id}/receipt',static fn(Request $r,array $p):Response=>$json($keys()->receipt((string)$p['id'])),$opts('key_register.view'));
    $router->get('/api/v1/my-keys/{id}/receipt',static fn(Request $r,array $p):Response=>$json($keys()->receipt((string)$p['id'],true)),$opts('key_register.self'));
    foreach(['accept','return']as$action)$router->post('/api/v1/my-keys/{id}/'.$action,static fn(Request $r,array $p):Response=>$json($keys()->selfAction((string)$p['id'],$action,$r->json())),$opts('key_register.self'));
    $router->get('/api/v1/replacement-preferences',static fn():Response=>$json($suggest()->preferences()),$opts('replacement_suggestions.view'));
    $router->post('/api/v1/replacement-preferences',static fn(Request $r):Response=>$json($suggest()->preference($r->json())),$opts('replacement_suggestions.manage'));
    $router->get('/api/v1/replacement-suggestions/{id}',static fn(Request $r,array $p):Response=>$json($suggest()->suggest((string)$p['id'])),$opts('replacement_suggestions.view'));
    $router->post('/api/v1/replacement-suggestions/{id}/approve',static fn(Request $r,array $p):Response=>$json($suggest()->approve((string)$p['id'],$r->json())),$opts('replacement_suggestions.manage'));
    $router->get('/api/v1/emergency-procedures',static fn(Request $r):Response=>$json($emergency()->workspace($r->queryParams())),$opts('emergency_procedures.view'));
    $router->post('/api/v1/emergency-procedures',static fn(Request $r):Response=>$json($emergency()->publish($r->json())),$opts('emergency_procedures.manage'));
    $router->post('/api/v1/emergency-exercises',static fn(Request $r):Response=>$json($emergency()->start($r->json())),$opts('emergency_procedures.manage'));
    $router->post('/api/v1/emergency-roll-call/{id}',static fn(Request $r,array $p):Response=>$json($emergency()->rollCall((string)$p['id'],$r->json())),$opts('emergency_procedures.manage'));
    $router->post('/api/v1/emergency-exercises/{id}/step',static fn(Request $r,array $p):Response=>$json($emergency()->completeStep((string)$p['id'],$r->json())),$opts('emergency_procedures.manage'));
    $router->post('/api/v1/emergency-exercises/{id}/finish',static fn(Request $r,array $p):Response=>$json($emergency()->finish((string)$p['id'],$r->json())),$opts('emergency_procedures.manage'));
    $router->get('/api/v1/company-branding',static fn():Response=>$json($company()->branding()),$opts('company_branding.read'));
    $router->get('/api/v1/company-workspace',static fn():Response=>$json($company()->overview()),$opts('company_workspace.view'));
    $router->post('/api/v1/company-branding',static fn(Request $r):Response=>$json($company()->saveBranding($r->json())),$opts('company_workspace.manage'));
    $router->post('/api/v1/company-setup',static fn(Request $r):Response=>$json($company()->completeCheck($r->json())),$opts('company_workspace.manage'));
    $router->post('/api/v1/company-setup/{code}/reopen',static fn(Request $r,array $p):Response=>$json($company()->reopenCheck((string)$p['code'])),$opts('company_workspace.manage'));
    $router->post('/api/v1/subscription-change-requests',static fn(Request $r):Response=>$json($company()->requestPlan($r->json())),$opts('company_workspace.manage'));
    $router->post('/api/v1/subscription-change-requests/{id}/cancel',static fn(Request $r,array $p):Response=>$json($company()->cancelPlan((string)$p['id'])),$opts('company_workspace.manage'));
    $router->get('/api/v1/workflow-language',static fn():Response=>$json($language()->preference()),$opts('workflow_languages.self'));
    $router->post('/api/v1/workflow-language',static fn(Request $r):Response=>$json($language()->setPreference($r->json())),$opts('workflow_languages.self'));
    $router->get('/api/v1/localized-workflow',static fn(Request $r):Response=>$json($language()->read($r->queryParams())),$opts('workflow_languages.view'));
    $router->post('/api/v1/workflow-translations',static fn(Request $r):Response=>$json($language()->publish($r->json())),$opts('workflow_languages.manage'));
    $router->get('/api/v1/workflow-translation-source',static fn(Request $r):Response=>$json($language()->reviewSource($r->queryParams())),$opts('workflow_languages.manage'));
    $router->get('/api/v1/my-translated-notifications',static fn():Response=>$json($language()->notifications()),$opts('workflow_languages.self'));
    $router->get('/api/v1/guard/localized-workflow',static fn(Request $r):Response=>$json($language()->read($r->queryParams(),true)),$opts('guard.self'));
};
